import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"外键与参照动作","description":"","frontmatter":{"title":"外键与参照动作","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fk-actions.md","filePath":"cs/fk-actions.md","lastUpdated":1789023840000}'),E={name:"cs/fk-actions.md"};function h(_,a,A,f,m,u){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="外键与参照动作" tabindex="-1">外键与参照动作 <a class="header-anchor" href="#外键与参照动作" aria-label="Permalink to &quot;外键与参照动作&quot;">​</a></h1><div class="epigraph"><p>外键要求引用的值在被参照关系里存在；删除或更新被参照元组时，级联、限制或置空是事先声明的动作。</p><footer>—— 据 Codd 对参照完整性；Date；SQL 标准对 FOREIGN KEY 动作的整理</footer></div><p><a href="/cs/keys-integrity">上一课</a>钉死候选键、主键与「引用是值」。本课不重讲超键。缺口是更新语义：删客户时订单怎么办？只声明外键而不声明动作，实现会拒绝或留下悬挂，应用各写各的。参照动作把政策收进模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/keys-integrity">键与完整性</a>留下外键作为值上的约束。删除被参照行：RESTRICT/NO ACTION 拒绝；CASCADE 删除依赖行；SET NULL 要求列可空（后课三值逻辑）。更新主键同样有级联或拒绝。缺口是<strong>参照动作</strong>，不是代数。</p><p><span class="marginnote">循环参照与延迟约束检查（事务末再验）是实现细节。本课只要求动作是模式的一部分，而不是触发器散文化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明：列集参照另一表的候选键，并给出 ON DELETE / ON UPDATE。插入依赖行时立即检查存在性。复合键必须整组对应。本课不把触发器替代外键当推荐默认。</p>',8)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEL%5B%22%E5%88%A0%E9%99%A4%E8%A2%AB%E5%8F%82%E7%85%A7%E5%85%83%E7%BB%84%22%5D%20--%3E%20REST%5B%22%E6%8B%92%E7%BB%9D%22%5D%0A%20%20DEL%20--%3E%20CAS%5B%22%E7%BA%A7%E8%81%94%E5%88%A0%E4%BE%9D%E8%B5%96%22%5D%0A%20%20DEL%20--%3E%20NUL%5B%22%E7%BD%AE%E7%A9%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>动作让完整性在修改时封闭，避免「先删后补」的窗口里出现悬挂指针式的值。查询代数假定实例满足约束；若动作与应用意图不符，那是模式选错，不是选择投影错。后课 SQL 的声明查询建立在合法实例上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入分片库之间的跨库外键（后课分片会放弃）。也不把外键当安全的授权。有了合法关系，如何用运算生成新关系，下一课关系代数。</p><p>后课默认：删除与更新的参照政策已在模式里。查询语言还没有。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>外键检查存在性；动作规定删改时的政策。</li><li>级联、拒绝、置空是声明，不是临时脚本。</li><li>关系代数下一课。</li><li>出处：Codd；Date；SQL 参照动作。</li></ul>',7))])}const B=i(E,[["render",h]]);export{D as __pageData,B as default};
